/bin/zsh -lc "cat > index.html <<'EOF'
<"'!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no" />
  <meta name="theme-color" content="#11110f" />
  <title>VELORA</title>
  <style>
    :root { color-scheme: dark; --ink: #f1eee6; --muted: #a9a59b; --line: rgba(239,230,213,.16); --panel: rgba(22,21,19,.76); --accent: #e5ad69; }
    * { box-sizing: border-box; }
    html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; background: #10100f; color: var(--ink); font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
    canvas { display: block; width: 100%; height: 100%; }
    .brand { position: fixed; z-index: 2; top: 27px; right: 34px; font-size: 11px; font-weight: 600; letter-spacing: .34em; color: rgba(247,241,228,.77); text-shadow: 0 1px 16px #000; }
    .panel { position: fixed; z-index: 3; left: 26px; bottom: 25px; width: 246px; padding: 16px 17px 14px; border: 1px solid var(--line); border-radius: 13px; background: var(--panel); box-shadow: 0 14px 44px rgba(0,0,0,.27); backdrop-filter: blur(20px) saturate(125%); -webkit-backdrop-filter: blur(20px) saturate(125%); }
    .row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
    .power-row { padding-bottom: 13px; border-bottom: 1px solid var(--line); }
    .label { color: var(--muted); font-size: 10px; letter-spacing: .13em; text-transform: uppercase; }
    .power-state { display: flex; align-items: center; gap: 8px; color: #e8e1d4; font-size: 12px; }
    .toggle { width: 35px; height: 20px; border: 1px solid rgba(255,255,255,.19); border-radius: 20px; padding: 2px; background: #494642; cursor: pointer; transition: .25s ease; }
    .toggle::before { content: ""; display: block; width: 14px; height: 14px; border-radius: 50%; background: #eee7d9; transition: .25s ease; box-shadow: 0 1px 4px #0008; }
    .toggle[aria-checked="true"] { background: #a96a37; border-color: #c78e58; box-shadow: 0 0 15px #d1814233; }
    .toggle[aria-checked="true"]::before { transform: translateX(15px); background: #fff2d9; }
    .section { margin-top: 14px; }
    .presets { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin-top: 8px; }
    .preset { height: 30px; padding: 0; border: 1px solid rgba(255,255,255,.15); border-radius: 7px; color: #eee9df; background: rgba(255,255,255,.035); cursor: pointer; font-size: 9px; letter-spacing: .01em; transition: .2s ease; }
    .preset:hover { background: rgba(255,255,255,.1); }
    .preset[aria-pressed="true"] { border-color: rgba(238,191,135,.8); box-shadow: inset 0 0 0 1px rgba(238,191,135,.19), 0 0 11px rgba(220,158,90,.12); color: #fff2df; }
    .swatch { display: block; width: 10px; height: 10px; margin: 0 auto 2px; border-radius: 50%; box-shadow: 0 0 7px currentColor; }
    .slider-row { margin-top: 14px; }
    .slider-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 7px; }
    output { min-width: 32px; text-align: right; color: #d8d0c3; font-size: 10px; font-variant-numeric: tabular-nums; }
    input[type="range"] { display: block; width: 100%; height: 3px; margin: 0; appearance: none; border-radius: 5px; background: linear-gradient(90deg, #c8894f 0%, #c8894f 50%, rgba(255,255,255,.2) 50%); outline: none; cursor: pointer; }
    input[type="range"]::-webkit-slider-thumb { appearance: none; width: 11px; height: 11px; border: 1px solid #fff0dd; border-radius: 50%; background: #d9a66b; box-shadow: 0 0 9px #e2a65f88; }
    input[type="range"]::-moz-range-thumb { width: 10px; height: 10px; border: 1px solid #fff0dd; border-radius: 50%; background: #d9a66b; box-shadow: 0 0 9px #e2a65f88; }
    .hint { display: flex; align-items: center; justify-content: space-between; margin-top: 14px; padding-top: 11px; border-top: 1px solid var(--line); color: rgba(228,222,211,.48); font-size: 9px; letter-spacing: .05em; }
    .orbit { padding: 5px 9px; border: 1px solid rgba(255,255,255,.14); border-radius: 6px; color: rgba(238,231,217,.72); background: transparent; font-size: 9px; cursor: pointer; }
    .orbit[aria-pressed="true"] { border-color: #c99059; color: #f2c897; }
    @media (max-width: 640px) { .brand { top: 17px; right: 18px; } .panel { left: 12px; bottom: 12px; width: min(230px, calc(100vw - 24px)); padding: 13px 14px 12px; } }
  </style>
  <script type="importmap">
    { "imports": { "three": "https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js", "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.161.0/examples/jsm/" } }
  </script>
</head>
<body>
  <div class="brand">VELORA</div>
  <section class="panel" aria-label="Lamp controls">
    <div class="row power-row">
      <span class="label">Power</span>
      <div class="power-state"><span id="powerText">On</span><button class="toggle" id="power" type="button" role="switch" aria-checked="true" aria-label="Power"></button></div>
    </div>
    <div class="section">
      <div class="label">Color</div>
      <div class="presets" role="group" aria-label="Color preset">
        <button class="preset" data-preset="classic" aria-pressed="true"><i class="swatch" style="color:#f05522;background:#f05522"></i>Classic</button>
        <button class="preset" data-preset="lagoon" aria-pressed="false"><i class="swatch" style="color:#49d4ca;background:#49d4ca"></i>Lagoon</button>
        <button class="preset" data-preset="orchid" aria-pressed="false"><i class="swatch" style="color:#d080ff;background:#d080ff"></i>Orchid</button>
        <button class="preset" data-preset="citrine" aria-pressed="false"><i class="swatch" style="color:#ffe48a;background:#ffe48a"></i>Citrine</button>
      </div>
    </div>
    <div class="slider-row">
      <div class="slider-head"><label class="label" for="heat">Heat</label><output id="heatOut">72%</output></div>
      <input id="heat" type="range" min="25" max="100" value="72" aria-label="Heat and flow speed" />
    </div>
    <div class="slider-row">
      <div class="slider-head"><label class="label" for="amount">Wax amount</label><output id="amountOut">62%</output></div>
      <input id="amount" type="range" min="35" max="100" value="62" aria-label="Wax amount" />
    </div>
    <div class="hint"><span>Drag to orbit · scroll to zoom</span><button class="orbit" id="orbit" type="button" aria-pressed="false">Auto orbit</button></div>
  </section>
  <script type="module">
    import * as THREE from '"'three';
    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
    import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
    import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
    import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
    import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
    import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';

    const MODEL = 'VELORA';
    const scene = new THREE.Scene();
    scene.background = new THREE.Color('#11110f');
    const camera = new THREE.PerspectiveCamera(34, innerWidth / innerHeight, .1, 45);
    camera.position.set(6.4, 4.2, 8.7);
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, powerPreference: 'high-performance' });
    renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.35));
    renderer.setSize(innerWidth, innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.transmissionResolutionScale = .65;
    document.body.appendChild(renderer.domElement);

    const pmrem = new THREE.PMREMGenerator(renderer);
    const env = pmrem.fromScene(new RoomEnvironment(), .04).texture;
    scene.environment = env;
    pmrem.dispose();

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.target.set(0, 2.03, 0);
    controls.enableDamping = true;
    controls.dampingFactor = .055;
    controls.minDistance = 3.55;
    controls.maxDistance = 10.8;
    controls.minPolarAngle = .12;
    controls.maxPolarAngle = Math.PI - .12;
    controls.update();

    scene.add(new THREE.HemisphereLight(0x8692a0, 0x211714, .22));
    const roomFill = new THREE.PointLight(0x8291a7, .75, 11, 2);
    roomFill.position.set(-3.7, 4.4, 2.3);
    scene.add(roomFill);
    const rimLight = new THREE.PointLight(0x9db6d1, 1.1, 8, 2);
    rimLight.position.set(1.2, 4.7, -2.1);
    scene.add(rimLight);

    function makeWoodTexture() {
      const c = document.createElement('canvas'); c.width = 512; c.height = 512;
      const ctx = c.getContext('2d');
      const grad = ctx.createLinearGradient(0, 0, 0, 512);
      grad.addColorStop(0, '#4a3022'); grad.addColorStop(.45, '#332219'); grad.addColorStop(1, '#241a15');
      ctx.fillStyle = grad; ctx.fillRect(0, 0, 512, 512);
      for (let i = 0; i < 110; i++) {
        const y = Math.random() * 512, amp = 1 + Math.random() * 7;
        ctx.beginPath(); ctx.moveTo(0, y);
        for (let x = 0; x <= 512; x += 18) ctx.lineTo(x, y + Math.sin(x * (.012 + Math.random() * .009) + i) * amp + Math.sin(x * .055 + i * 3) * 1.4);
        ctx.strokeStyle = "'`rgba(${i % 3 ? '"'185,128,83' : '15,9,6'},"'${.025 + Math.random() * .07})`;
        ctx.lineWidth = .5 + Math.random() * 2.2; ctx.stroke();
      }
      const t = new THREE.CanvasTexture(c); t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(4, 4); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4; return t;
    }
    const wood = new THREE.Mesh(new THREE.PlaneGeometry(200, 200), new THREE.MeshStandardMaterial({ map: makeWoodTexture(), roughness: .35, metalness: .08 }));
    wood.rotation.x = -Math.PI / 2; wood.position.y = -.025; wood.receiveShadow = true; scene.add(wood);
    const tableEdge = new THREE.Mesh(new THREE.BoxGeometry(200, .28, .42), new THREE.MeshStandardMaterial({ color: '"'#211712', roughness: .48 }));
    tableEdge.position.set(0, -.16, .48); tableEdge.receiveShadow = true; scene.add(tableEdge);

    const wall = new THREE.Mesh(new THREE.PlaneGeometry(28, 13), new THREE.MeshStandardMaterial({ color: '#171817', roughness: .94, metalness: .02 }));
    wall.position.set(0, 5.1, -3.9); scene.add(wall);
    const wallGlow = new THREE.Mesh(new THREE.PlaneGeometry(8, 6), new THREE.MeshBasicMaterial({ color: '#24190f', transparent: true, opacity: .22, depthWrite: false }));
    wallGlow.position.set(0, 2.35, -3.86); scene.add(wallGlow);

    // A few quiet objects establish tabletop scale without competing with the lamp.
    const bookMat = [new THREE.MeshStandardMaterial({ color: '#26302f', roughness: .7 }), new THREE.MeshStandardMaterial({ color: '#553529', roughness: .67 })];
    function book(x, y, z, sx, sy, sz, mat, rot = 0) {
      const b = new THREE.Mesh(new THREE.BoxGeometry(sx, sy, sz), mat); b.position.set(x, y, z); b.rotation.y = rot; b.castShadow = true; b.receiveShadow = true; scene.add(b);
      const line = new THREE.Mesh(new THREE.BoxGeometry(sx * .72, .009, .012), new THREE.MeshStandardMaterial({ color: '#b2905c', metalness: .55, roughness: .34 }));
      line.position.set(x, y + sy * .22, z + sz * .501); line.rotation.y = rot; scene.add(line);
    }
    book(1.32, .12, -.1, .83, .23, .62, bookMat[0], -.12);
    book(1.36, .35, -.08, .76, .21, .56, bookMat[1], .08);
    const cupMat = new THREE.MeshPhysicalMaterial({ color: '#333733', roughness: .19, clearcoat: .55, clearcoatRoughness: .15 });
    const cup = new THREE.Mesh(new THREE.CylinderGeometry(.17, .14, .38, 40, 1, true), cupMat); cup.position.set(-1.25, .2, -.12); cup.castShadow = true; scene.add(cup);
    const cupFoot = new THREE.Mesh(new THREE.TorusGeometry(.145, .018, 8, 40), cupMat); cupFoot.rotation.x = Math.PI / 2; cupFoot.position.set(-1.25, .035, -.12); scene.add(cupFoot);

    const lamp = new THREE.Group(); scene.add(lamp);
    const silver = new THREE.MeshPhysicalMaterial({ color: '#d7d3cc', metalness: .91, roughness: .2, envMapIntensity: 1.35, clearcoat: .55, clearcoatRoughness: .16 });
    const darkMetal = new THREE.MeshPhysicalMaterial({ color: '#514b43', metalness: .82, roughness: .27, envMapIntensity: 1.25 });
    function lathe(points, material, segments = 96) {
      const g = new THREE.LatheGeometry(points.map(([r, y]) => new THREE.Vector2(r, y)), segments);
      const m = new THREE.Mesh(g, material); m.castShadow = true; m.receiveShadow = true; lamp.add(m); return m;
    }
    lathe([[0,.04],[.60,.04],[.67,.075],[.69,.12],[.67,.16],[.56,.18],[.49,.33],[.43,.55],[.385,.78],[.37,.88],[.39,.93],[.42,.95],[.43,.99],[.40,1.03],[0,1.03]], silver);
    lathe([[.62,.045],[.68,.075],[.685,.12],[.62,.155],[.59,.13]], darkMetal);
    lathe([[.41,.83],[.43,.87],[.43,.93],[.40,.96]], darkMetal);
    lathe([[.35,.91],[.38,.95],[.39,1.02],[.37,1.08],[.35,1.1],[.32,1.06]], silver);

    const glassProfile = [[0,.78],[.385,.78],[.412,.795],[.437,.83],[.448,.9],[.478,1.1],[.516,1.42],[.542,1.82],[.55,2.22],[.538,2.62],[.51,2.96],[.47,3.23],[.42,3.43],[.39,3.52],[.373,3.535],[.358,3.51],[.371,3.47],[.4,3.39],[.447,3.21],[.48,2.94],[.506,2.61],[.518,2.22],[.51,1.82],[.488,1.43],[.455,1.12],[.425,.91],[.409,.84],[.39,.82],[0,.82]];
    const glass = lathe(glassProfile, new THREE.MeshPhysicalMaterial({ color: '#f8f5eb', metalness: 0, roughness: .035, transmission: .96, thickness: .16, ior: 1.47, clearcoat: 1, clearcoatRoughness: .035, envMapIntensity: 1.35, attenuationColor: '#f3eddf', attenuationDistance: 5, side: THREE.DoubleSide }));
    glass.castShadow = false; glass.renderOrder = 4;

    const liquidProfile = [[0,.824],[.385,.824],[.405,.85],[.425,.94],[.455,1.14],[.486,1.43],[.51,1.82],[.518,2.22],[.506,2.61],[.48,2.94],[.447,3.2],[.41,3.37],[.39,3.39],[0,3.39]];
    const liquidMat = new THREE.MeshPhysicalMaterial({ color: '#e8b84f', metalness: 0, roughness: .11, transmission: .21, thickness: 1.3, ior: 1.33, transparent: true, opacity: .3, depthWrite: false, envMapIntensity: .5, attenuationColor: '#eac566', attenuationDistance: 2.7, side: THREE.DoubleSide });
    const liquid = lathe(liquidProfile, liquidMat); liquid.castShadow = false; liquid.renderOrder = 2;

    const topTrim = new THREE.Mesh(new THREE.TorusGeometry(.395, .025, 12, 96), silver); topTrim.rotation.x = Math.PI / 2; topTrim.position.y = 3.48; lamp.add(topTrim);
    lathe([[.37,3.43],[.405,3.45],[.423,3.5],[.42,3.55],[.38,3.57],[.34,3.64],[.28,3.72],[.20,3.78],[.08,3.81],[0,3.81]], silver);
    lathe([[.365,3.55],[.39,3.58],[.37,3.62],[.34,3.61]], darkMetal);
    lathe([[.19,3.77],[.20,3.8],[.18,3.825],[.14,3.83],[.1,3.82]], darkMetal);

    const switchWell = new THREE.Mesh(new THREE.CylinderGeometry(.055,.055,.025,32), darkMetal); switchWell.position.set(.47,.19,.12); switchWell.rotation.z = Math.PI/2; lamp.add(switchWell);
    const switchToggle = new THREE.Mesh(new THREE.SphereGeometry(.045,20,14), new THREE.MeshPhysicalMaterial({ color:'#d2a56b', metalness:.68, roughness:.22, emissive:'#5a2c0c', emissiveIntensity:.35 }));
    switchToggle.position.set(.505,.2,.12); lamp.add(switchToggle);

    // The cord bends over the tabletop and disappears past the frame.
    const cordCurve = new THREE.CatmullRomCurve3([new THREE.Vector3(-.03,.075,-.63),new THREE.Vector3(-.02,.05,-.78),new THREE.Vector3(.06,.035,-.96),new THREE.Vector3(.25,.025,-1.11),new THREE.Vector3(.6,.022,-1.2),new THREE.Vector3(1.08,.02,-1.27),new THREE.Vector3(1.65,.02,-1.34),new THREE.Vector3(2.25,.02,-1.37)]);
    const cord = new THREE.Mesh(new THREE.TubeGeometry(cordCurve, 80, .018, 8, false), new THREE.MeshStandardMaterial({ color:'#171715', roughness:.82 })); cord.castShadow = true; scene.add(cord);

    const bulbMat = new THREE.MeshStandardMaterial({ color: '#ffc878', emissive: '#ff8d30', emissiveIntensity: 4.2, roughness: .25 });
    const bulb = new THREE.Mesh(new THREE.SphereGeometry(.12, 32, 20), bulbMat); bulb.position.set(0, 1.02, 0); lamp.add(bulb);
    const bulbStem = new THREE.Mesh(new THREE.CylinderGeometry(.045,.07,.14,24), darkMetal); bulbStem.position.set(0,.89,0); lamp.add(bulbStem);
    const bulbGlow = new THREE.PointLight(0xff8c37, 16, 4.7, 1.55); bulbGlow.position.set(0,1.08,0); bulbGlow.castShadow = true; bulbGlow.shadow.mapSize.set(512,512); bulbGlow.shadow.bias = -.00035; bulbGlow.shadow.radius = 5; lamp.add(bulbGlow);
    const spill = new THREE.PointLight(0xff9b4c, 6, 7.2, 2); spill.position.set(0,1.18,.15); scene.add(spill);

    // A single raymarched smooth-union volume creates connected, stretchable wax.
    const waxMax = 12;
    const waxMaterial = new THREE.ShaderMaterial({
      glslVersion: THREE.GLSL3,
      uniforms: {
        uCameraLocal: { value: new THREE.Vector3() }, uTime: { value: 0 }, uPower: { value: 1 }, uWaxColor: { value: new THREE.Color('#d62c19') },
        uBlobs: { value: Array.from({length:waxMax}, () => new THREE.Vector4()) },
        uShape: { value: Array.from({length:waxMax}, () => new THREE.Vector4()) },
        uBlobCount: { value: 0 }, uAmount: { value: .62 }, uBulbColor: { value: new THREE.Color('#ff9a42') },
        uLightLocal: { value: new THREE.Vector3(0,-1.12,0) },
      },
      vertexShader: "'`
        out vec3 vLocal;
        void main() { vLocal = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }
      `,
      fragmentShader: `
        precision highp float;
        in vec3 vLocal;
        out vec4 fragColor;
        uniform vec3 uCameraLocal, uLightLocal;
        uniform float uTime, uPower, uAmount;
        uniform vec3 uWaxColor, uBulbColor;
        uniform vec4 uBlobs[12], uShape[12];
        uniform int uBlobCount;
        #include <tonemapping_pars_fragment>
        #include <colorspace_pars_fragment>
        float smin(float a, float b, float k) {
          float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
          return mix(b, a, h) - k * h * (1.0 - h);
        }
        float sdEllipsoid(vec3 p, vec3 r) {
          float k0 = length(p / r);
          float k1 = length(p / (r * r));
          return k0 * (k0 - 1.0) / max(k1, 0.0001);
        }
        float field(vec3 p) {
          float d = sdEllipsoid(p - vec3(0.0, -1.16, 0.0), vec3(0.43 * sqrt(uAmount), 0.19, 0.43 * sqrt(uAmount)));
          for (int i = 0; i < 12; i++) {
            if (i >= uBlobCount) break;
            vec4 b = uBlobs[i]; vec4 sh = uShape[i];
            vec3 q = p - b.xyz;
            float wave = sin(q.y * 9.0 + uTime * 1.4 + sh.w * 6.0) * cos(q.x * 7.0 - uTime * .7 + q.z * 4.0);
            q.x += wave * .016 * (0.25 + sh.z);
            q.z += sin(q.y * 7.5 - uTime * 1.1 + sh.w * 8.0) * .012;
            float dist = length(vec3(q.x, q.y / max(sh.x, .85), q.z)) * max(sh.x, .85) - b.w;
            dist += wave * .008;
            d = smin(d, dist, .12 + b.w * .12);
          }
          return d;
        }
        vec3 normalAt(vec3 p) {
          const float e = .008;
          return normalize(vec3(field(p + vec3(e,0,0)) - field(p - vec3(e,0,0)), field(p + vec3(0,e,0)) - field(p - vec3(0,e,0)), field(p + vec3(0,0,e)) - field(p - vec3(0,0,e))));
        }
        void main() {
          vec3 ro = uCameraLocal;
          vec3 rd = normalize(vLocal - ro);
          vec3 lo = vec3(-.64,-1.41,-.64), hi = vec3(.64,1.41,.64);
          vec3 inv = 1.0 / rd;
          vec3 ta = (lo - ro) * inv, tb = (hi - ro) * inv;
          vec3 tmin = min(ta,tb), tmax = max(ta,tb);
          float t0 = max(max(tmin.x,tmin.y),tmin.z), t1 = min(min(tmax.x,tmax.y),tmax.z);
          float endT = min(t1, length(vLocal-ro));
          float t = max(t0, 0.0); float hit = -1.0;
          for (int i=0; i<78; i++) {
            if (t > endT) break;
            float d = field(ro + rd*t);
            if (d < .0045) { hit=t; break; }
            t += clamp(d * .72, .009, .085);
          }
          if (hit < 0.0) discard;
          vec3 p = ro + rd * hit;
          vec3 n = normalAt(p);
          vec3 l = normalize(uLightLocal - p);
          vec3 v = normalize(ro - p);
          float ndl = max(dot(n,l), 0.0);
          float back = pow(max(dot(-l, rd),0.0), 2.0) * (0.25 + .75 * uPower);
          float edge = pow(1.0 - abs(dot(n,v)), 2.1);
          float hot = exp(-max((p.y + 1.18),0.0) * 1.65) * uPower;
          float thickness = 1.0 / max(abs(dot(n,v)), .22);
          float thinGlow = exp(-thickness * .48);
          vec3 halfV = normalize(l+v);
          float spec = pow(max(dot(n,halfV),0.0), 48.0);
          vec3 deep = uWaxColor * (.42 + .42 * ndl) * (1.0 - .14 * (1.0-thinGlow));
          vec3 scatter = uWaxColor * (back * .72 + edge * .38 + hot * .26);
          vec3 color = deep + scatter + uBulbColor * (hot * .24 + thinGlow * back * .12) + vec3(1.0,.78,.54) * spec * .48;
          color *= (.82 + .18 * sin(uTime * .75 + p.y * 2.4));
          float alpha = .94;
          vec4 clip = projectionMatrix * modelViewMatrix * vec4(p,1.0);
          gl_FragDepth = (clip.z / clip.w) * .5 + .5;
          fragColor = vec4(color, alpha);
          #include <tonemapping_fragment>
          #include <colorspace_fragment>
        }
      `,
      side: THREE.FrontSide,
      depthWrite: true,
      depthTest: true,
      toneMapped: true,
    });
    const waxProxy = new THREE.Mesh(new THREE.BoxGeometry(1.28, 2.82, 1.28), waxMaterial);
    waxProxy.position.y = 2.19; waxProxy.renderOrder = 1; scene.add(waxProxy);

    const presets = {
